package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.DeliveryRepositoryPort;import com.yeyamo_mobile.api.notification_service.domain.*;
@Component public class JpaDeliveryAdapter implements DeliveryRepositoryPort{private final SpringDeliveryRepository repo;public JpaDeliveryAdapter(SpringDeliveryRepository r){repo=r;}public Delivery save(Delivery d){DeliveryEntity e=repo.findById(d.id()).orElseGet(DeliveryEntity::new);e.id=d.id();e.notificationId=d.notificationId();e.channel=d.channel();e.destination=d.destination();e.status=d.status();e.attempts=d.attempts();e.nextAttemptAt=d.nextAttemptAt();e.deliveredAt=d.deliveredAt();e.lastError=d.lastError();return domain(repo.save(e));}public List<Delivery>findDue(Instant now,int limit){return repo.findByStatusInAndNextAttemptAtLessThanEqualOrderByNextAttemptAtAsc(List.of(DeliveryStatus.PENDING,DeliveryStatus.RETRY),now,PageRequest.of(0,limit)).stream().map(this::domain).toList();}private Delivery domain(DeliveryEntity e){return new Delivery(e.id,e.notificationId,e.channel,e.destination,e.status,e.attempts,e.nextAttemptAt,e.deliveredAt,e.lastError);}}
